import polars as pl


def mean_score(df: pl.DataFrame) -> pl.DataFrame:
    """Mean score per region among respondents who answered."""
    return (
        df.group_by("region")
        .agg(mean_score=pl.col("score").mean())
        .sort("region")
    )
